using System.Data;using System.Data.Common;using AiCare.Application;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Storage;
namespace AiCare.Api;
[ApiController,Authorize(Roles="Administrator,BackOffice")][Route("api/phase1/finance/invoice-runs")]
public sealed class InvoiceRunsController(CareDbContext db,ITenantContext tenant,ICurrentUserContext user):ControllerBase
{
 Guid Branch=>tenant.BranchId??TenantDefaults.BranchId;
 sealed record VatRow(Guid Id,string Treatment,decimal Rate,string Rounding,string Reference,decimal Amount=0);
 Task<List<VatRow>> Vat(Guid source,DateOnly day,bool recharge,CancellationToken t)=>Query($"select v.treatment_id,v.treatment,v.rate,v.rounding_mode,t.reference from {(recharge?"finance_resolve_recharge_vat":"finance_resolve_vat")}(@event,@day) v join finance_vat_treatments t on t.id=v.treatment_id",c=>{Add(c,"event",source);Add(c,"day",day);},r=>new VatRow(r.GetGuid(0),r.GetString(1),r.GetDecimal(2),r.GetString(3),r.GetString(4)),t);
 [HttpPost("preview")]
 public async Task<IActionResult> Preview(InvoiceRunRequest r,CancellationToken t){if(r.PeriodStart>r.PeriodEnd)return BadRequest(new{message="Invalid invoice period."});var rows=await Eligible(r,t);var blocked=await Blocked(r,t);return Ok(new{blockedEvents=blocked.Count,blockedEventIds=blocked,eventCount=rows.Select(x=>x.Id).Distinct().Count(),shareCount=rows.Count,invoiceCount=rows.Select(x=>(x.ServiceUserId,x.FunderId,x.BranchId,x.Currency)).Distinct().Count(),totalAmount=rows.Sum(x=>x.Amount),currencyTotals=rows.GroupBy(x=>x.Currency).Select(x=>new{currency=x.Key,amount=x.Sum(e=>e.Amount)}),events=rows});}
 [HttpPost]
 public async Task<IActionResult> Generate(InvoiceRunRequest r,CancellationToken t){if(r.PeriodStart>r.PeriodEnd||string.IsNullOrWhiteSpace(r.IdempotencyKey))return BadRequest(new{message="Valid period and idempotency key are required."});return await db.Database.CreateExecutionStrategy().ExecuteAsync<IActionResult>(async()=>{await using var tx=await db.Database.BeginTransactionAsync(t);await Exec("select pg_advisory_xact_lock(hashtextextended(@billingLock,0))",c=>Add(c,"billingLock",$"finance-billing:{tenant.OrganizationId}"),t);await Exec("select pg_advisory_xact_lock(hashtextextended(@lock,0))",c=>Add(c,"lock",$"invoice-run:{tenant.OrganizationId}"),t);var existing=await Query("select id,status,event_count,invoice_count,total_amount from finance_invoice_runs where organization_id=@organization and idempotency_key=@key",c=>Add(c,"key",r.IdempotencyKey),x=>new{Id=x.GetGuid(0),Status=x.GetString(1),Events=x.GetInt32(2),Invoices=x.GetInt32(3),Total=x.GetDecimal(4)},t);if(existing.Count>0){await tx.RollbackAsync(t);return Ok(existing[0]);}var blocked=await Blocked(r,t);if(blocked.Count>0)return Conflict(new{message="Approved events have missing or stale contract/attendance lineage. Review the source before creating invoices; legacy approvals are not automatically trusted.",blockedEvents=blocked.Count,blockedEventIds=blocked});var events=await Eligible(r,t);if(events.Count==0){await tx.RollbackAsync(t);return Conflict(new{message="No approved uninvoiced billable events are available."});}if(events.Select(x=>x.Currency).Distinct(StringComparer.OrdinalIgnoreCase).Skip(1).Any()){await tx.RollbackAsync(t);return Conflict(new{message="Invoice runs must contain one currency. Generate separate runs by funder or period."});}var run=Guid.NewGuid();await Exec("insert into finance_invoice_runs(id,organization_id,branch_id,period_start,period_end,funder_id,status,requested_by,idempotency_key) values(@id,@organization,@runBranch,@start,@end,@funder,'Processing',@actor,@key)",c=>{Add(c,"id",run);Add(c,"runBranch",tenant.IsOrganizationWide?null:Branch);Add(c,"start",r.PeriodStart);Add(c,"end",r.PeriodEnd);Add(c,"funder",r.FunderId);Add(c,"key",r.IdempotencyKey);},t);var invoices=0;
 foreach(var group in events.GroupBy(x=>new{x.ServiceUserId,x.FunderId,x.FunderName,x.Currency,x.BranchId})){var items=group.ToList();var profile=await Profile(group.Key.BranchId,DateTimeOffset.UtcNow,t);if(profile is null)return Conflict(new{message=$"Invoice settings must be configured for branch {group.Key.BranchId}."});if(!string.Equals(group.Key.Currency,profile.Currency,StringComparison.OrdinalIgnoreCase))return Conflict(new{message=$"Invoice currency {group.Key.Currency} does not match the effective system currency {profile.Currency}. Create a separate effective settings version before invoicing."});var payers=await Query("select name,billing_address,payment_terms_days from finance_funders where id=@payer and organization_id=@organization and (branch_id is null or branch_id=@invoiceBranch) and currency=@currency",c=>{Add(c,"payer",group.Key.FunderId);Add(c,"invoiceBranch",group.Key.BranchId);Add(c,"currency",group.Key.Currency);},x=>new{Name=x.GetString(0),Address=x.GetString(1),Terms=x.GetInt32(2)},t);if(payers.Count!=1)return Conflict(new{message="Invoice payer must match the invoice tenant, branch and currency."});var payer=payers[0];var paymentTermsDays=payer.Terms>0?payer.Terms:profile.Terms;var person=await db.ServiceUsers.AsNoTracking().SingleAsync(x=>x.Id==group.Key.ServiceUserId&&x.OrganizationId==tenant.OrganizationId&&x.BranchId==group.Key.BranchId,t);var invoiceDate=DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Europe/London")).DateTime);var taxes=new List<VatRow>();foreach(var source in items){var applicable=await Vat(source.Id,invoiceDate,source.IsRecharge,t);if(applicable.Count!=1)return Conflict(new{message="Exactly one approved adviser VAT treatment must cover each supply.",eventId=source.Id});taxes.Add(applicable[0] with {Amount=Math.Round(source.Amount*applicable[0].Rate/100m,2,applicable[0].Rounding=="ToEven"?MidpointRounding.ToEven:MidpointRounding.AwayFromZero)});}if(profile.RoundingPolicy=="Late"){foreach(var taxGroup in taxes.Select((tax,index)=>(tax,index)).GroupBy(x=>x.tax.Id)){var indexes=taxGroup.Select(x=>x.index).ToList();var rule=taxes[indexes[0]];var target=Math.Round(indexes.Sum(i=>items[i].Amount)*rule.Rate/100m,2,rule.Rounding=="ToEven"?MidpointRounding.ToEven:MidpointRounding.AwayFromZero);var last=indexes[^1];taxes[last]=taxes[last] with {Amount=taxes[last].Amount+(target-indexes.Sum(i=>taxes[i].Amount))};}}var net=items.Sum(x=>x.Amount);var vat=taxes.Sum(x=>x.Amount);var gross=net+vat;var headerRate=taxes.Select(x=>x.Rate).Distinct().Count()==1?taxes[0].Rate:0m;var taxNote=string.Join("; ",taxes.Select(x=>$"{x.Treatment} {x.Rate:0.####}% — {x.Reference}").Distinct());var number=await NextNumber(invoiceDate.Year,t);var invoice=new Invoice(Guid.NewGuid(),group.Key.ServiceUserId,group.Key.FunderName,gross,"Generated",DateTimeOffset.UtcNow,tenant.OrganizationId,group.Key.BranchId);db.Invoices.Add(invoice);await db.SaveChangesAsync(t);await Exec("""insert into finance_invoice_details(invoice_id,organization_id,branch_id,invoice_number,invoice_date,due_date,payment_terms,provider_name,provider_address,provider_email,provider_phone,company_number,vat_number,customer_name,customer_address,funder_name,remittance_details,currency,net_amount,vat_rate,vat_amount,gross_amount,vat_exemption_reason,logo_content_type,logo_bytes,logo_sha256,care_recipient_id,care_recipient_name,payer_id) values(@invoice,@organization,@lineBranch,@number,@date,@due,@terms,@provider,@address,@email,@phone,@company,@vatNumber,@customer,@customerAddress,@funderName,@remittance,@currency,@net,@vatRate,@vat,@gross,@exemption,@logoType,@logoBytes,@logoHash,@recipientId,@recipientName,@payerId)""",c=>{Add(c,"invoice",invoice.Id);Add(c,"lineBranch",group.Key.BranchId);Add(c,"number",number);Add(c,"date",invoiceDate);Add(c,"due",invoiceDate.AddDays(paymentTermsDays));Add(c,"terms",$"Payment due within {paymentTermsDays} days");Add(c,"provider",profile.Name);Add(c,"address",profile.Address);Add(c,"email",profile.Email);Add(c,"phone",profile.Phone);Add(c,"company",profile.Company);Add(c,"vatNumber",profile.VatNumber);Add(c,"customer",payer.Name);Add(c,"customerAddress",payer.Address);Add(c,"payerId",group.Key.FunderId);Add(c,"recipientId",person.Id);Add(c,"recipientName",person.FullName);Add(c,"funderName",group.Key.FunderName);Add(c,"remittance",profile.Remittance);Add(c,"currency",group.Key.Currency);Add(c,"net",net);Add(c,"vatRate",headerRate);Add(c,"vat",vat);Add(c,"gross",gross);Add(c,"exemption",taxNote);Add(c,"logoType",profile.LogoType);Add(c,"logoBytes",profile.LogoBytes);Add(c,"logoHash",profile.LogoHash);},t);
  for(var lineIndex=0;lineIndex<items.Count;lineIndex++){var e=items[lineIndex];await Exec("""insert into finance_invoice_lines(id,invoice_id,visit_id,service_user_id,organization_id,branch_id,description,quantity,unit_rate,amount,funding_source,billable_event_id,invoice_run_id,event_share_id,recharge_id,vat_amount) values(@line,@invoice,@visit,@person,@organization,@lineBranch,@description,@quantity,@rate,@amount,@funding,@event,@run,@share,@recharge,@vatAmount)""",c=>{Add(c,"line",Guid.NewGuid());Add(c,"share",e.ShareId);Add(c,"invoice",invoice.Id);Add(c,"visit",e.VisitId);Add(c,"person",e.ServiceUserId);Add(c,"lineBranch",e.BranchId);Add(c,"description",e.Description);Add(c,"quantity",e.Quantity);Add(c,"rate",e.UnitRate);Add(c,"amount",e.Amount);Add(c,"funding",e.FunderName);Add(c,"event",e.IsRecharge?null:e.Id);Add(c,"recharge",e.IsRecharge?e.Id:null);Add(c,"vatAmount",taxes[lineIndex].Amount);Add(c,"run",run);},t);if(!e.IsRecharge)await Exec("update finance_billable_events e set status='Invoiced',revision=revision+1 where e.id=@event and e.status='Approved' and (e.allocation_version_id is null or not exists(select 1 from finance_event_shares s where s.billable_event_id=e.id and s.amount>0 and not exists(select 1 from finance_invoice_lines l where l.event_share_id=s.id)))",c=>Add(c,"event",e.Id),t);}invoices++;}
 var total=events.Sum(x=>x.Amount);await Exec("update finance_invoice_runs set status='Completed',completed_at=now(),event_count=@events,invoice_count=@invoices,total_amount=@total where id=@run",c=>{Add(c,"run",run);Add(c,"events",events.Select(x=>x.Id).Distinct().Count());Add(c,"invoices",invoices);Add(c,"total",total);},t);Audit("INVOICE_RUN_CREATED","InvoiceRun",run);await db.SaveChangesAsync(t);await tx.CommitAsync(t);return Created($"/api/phase1/finance/invoice-runs/{run}",new{id=run,status="Completed",eventCount=events.Select(x=>x.Id).Distinct().Count(),shareCount=events.Count,invoiceCount=invoices,totalAmount=total});});}
 async Task<List<Guid>> Blocked(InvoiceRunRequest r,CancellationToken t)=>await Query("""
  select e.id from finance_billable_events e where e.organization_id=@organization and (@wide or e.branch_id=@branch) and e.status in ('Approved','Invoiced')
   and e.service_date between @start and @end and (@funder is null or e.funder_id=@funder or exists(select 1 from finance_event_shares s where s.billable_event_id=e.id and s.funder_id=@funder))
   and not finance_source_current(e.id) and (
     (e.allocation_version_id is null and not exists(select 1 from finance_invoice_lines l where l.billable_event_id=e.id and l.organization_id=e.organization_id))
     or exists(select 1 from finance_event_shares s where s.billable_event_id=e.id and s.amount>0 and (@funder is null or s.funder_id=@funder) and not exists(select 1 from finance_invoice_lines l where l.event_share_id=s.id)))
  """,c=>{Add(c,"start",r.PeriodStart);Add(c,"end",r.PeriodEnd);Add(c,"funder",r.FunderId);},x=>x.GetGuid(0),t);
 async Task<List<EligibleEvent>> Eligible(InvoiceRunRequest r,CancellationToken t)=>await Query("""
  select e.id,e.visit_id,e.service_user_id,payer.funder_id,f.name,e.branch_id,e.service_date,
    case when payer.share_id is null then e.quantity else 1 end,
    case when payer.share_id is null then e.unit_rate else payer.amount end,payer.amount,e.currency,
    coalesce(v."VisitType",'Care service') || ' - ' || e.calculation_explanation || case when payer.share_id is null then '' else ' - Approved funding share of ' || e.final_amount || ' ' || trim(e.currency) end,payer.share_id,false is_recharge
  from finance_billable_events e
  cross join lateral (
    select null::uuid share_id,e.funder_id,e.final_amount amount where e.allocation_version_id is null
    union all select s.id,s.funder_id,s.amount from finance_event_shares s where s.billable_event_id=e.id and s.organization_id=e.organization_id and s.amount>0
  ) payer
  join finance_funders f on f.id=payer.funder_id and f.organization_id=e.organization_id and (f.branch_id is null or f.branch_id=e.branch_id) and f.currency=e.currency
  left join "Visits" v on v."Id"=e.visit_id and v."OrganizationId"=e.organization_id
  where e.organization_id=@organization and (@wide or e.branch_id=@branch) and e.status in ('Approved','Invoiced') and finance_source_current(e.id)
    and e.service_date between @start and @end and (@funder is null or payer.funder_id=@funder)
    and not exists(select 1 from finance_invoice_lines l where l.organization_id=e.organization_id and
      ((payer.share_id is null and l.billable_event_id=e.id and l.event_share_id is null) or l.event_share_id=payer.share_id))
  union all
  select r.id,null::uuid,r.service_user_id,r.funder_id,f.name,r.branch_id,r.service_date,
    1::numeric,r.net_amount,r.net_amount,r.currency,'Expense recharge - '||p.service_type||' - '||r.reason,null::uuid,true
  from finance_expense_recharges r join finance_recharge_policies p on p.id=r.policy_id
    join finance_funders f on f.id=r.funder_id and f.organization_id=r.organization_id and (f.branch_id is null or f.branch_id=r.branch_id) and f.currency=r.currency
  where r.organization_id=@organization and (@wide or r.branch_id=@branch) and r.status='Approved'
    and r.service_date between @start and @end and (@funder is null or r.funder_id=@funder)
    and not exists(select 1 from finance_invoice_lines l where l.recharge_id=r.id)
  order by 7,1,4
  """,c=>{Add(c,"start",r.PeriodStart);Add(c,"end",r.PeriodEnd);Add(c,"funder",r.FunderId);},x=>new EligibleEvent(x.GetGuid(0),x.IsDBNull(1)?null:x.GetGuid(1),x.GetGuid(2),x.GetGuid(3),x.GetString(4),x.GetGuid(5),x.GetFieldValue<DateOnly>(6),x.GetDecimal(7),x.GetDecimal(8),x.GetDecimal(9),x.GetString(10).Trim(),x.GetString(11),x.IsDBNull(12)?null:x.GetGuid(12),x.GetBoolean(13)),t);
 async Task<ProfileRow?> Profile(Guid invoiceBranch,DateTimeOffset effectiveAt,CancellationToken t){await Exec("select pg_advisory_xact_lock(hashtextextended(@lock,0))",c=>Add(c,"lock",$"invoice-profile:{tenant.OrganizationId}:{invoiceBranch}"),t);var x=await Query("""select coalesce(v.profile_snapshot->>'providerName',p.provider_name),coalesce(v.profile_snapshot->>'providerAddress',p.provider_address),coalesce(v.profile_snapshot->>'providerEmail',p.provider_email),coalesce(v.profile_snapshot->>'providerPhone',p.provider_phone),coalesce(v.profile_snapshot->>'companyNumber',p.company_number),coalesce(v.profile_snapshot->>'vatNumber',p.vat_number),coalesce(v.profile_snapshot->>'remittanceDetails',p.remittance_details),coalesce((v.profile_snapshot->>'paymentTermsDays')::int,p.default_payment_terms_days),coalesce((v.profile_snapshot->>'vatRate')::numeric,p.default_vat_rate),coalesce(v.profile_snapshot->>'vatExemptionReason',p.vat_exemption_reason),p.logo_content_type,p.logo_bytes,p.logo_sha256,coalesce(v.profile_snapshot->>'defaultCurrency',trim(p.default_currency)),coalesce(v.profile_snapshot->>'currencySymbol',p.currency_symbol),coalesce(v.profile_snapshot->>'taxLabel',p.tax_label),coalesce(v.profile_snapshot->>'vatRoundingPolicy',p.vat_rounding_policy) from finance_invoice_profiles p left join lateral (select profile_snapshot from finance_invoice_profile_versions where organization_id=p.organization_id and branch_id=p.branch_id and effective_from<=@effectiveAt order by effective_from desc,version desc limit 1)v on true where p.organization_id=@organization and p.branch_id=@profileBranch""",c=>{Add(c,"profileBranch",invoiceBranch);Add(c,"effectiveAt",effectiveAt);},r=>new ProfileRow(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetInt32(7),r.GetDecimal(8),r.GetString(9),r.IsDBNull(10)?null:r.GetString(10),r.IsDBNull(11)?null:(byte[])r[11],r.IsDBNull(12)?null:r.GetString(12),r.GetString(13),r.GetString(14),r.GetString(15),r.GetString(16)),t);if(x.Count>0)return x[0];return null;}
 async Task<string> NextNumber(int year,CancellationToken t){await using var c=await Command("""with settings as (select custom_numbering_enabled,invoice_number_prefix,invoice_number_start,invoice_number_padding from finance_invoice_profiles where organization_id=@organization and branch_id=@numberBranch), allocated as (insert into finance_invoice_sequences(organization_id,invoice_year,next_value) values(@organization,@year,coalesce((select invoice_number_start from settings),1)+1) on conflict(organization_id,invoice_year) do update set next_value=finance_invoice_sequences.next_value+1 returning next_value-1) select case when coalesce((select custom_numbering_enabled from settings),false) then coalesce((select invoice_number_prefix from settings),'INV-')||@year||'-'||lpad(allocated::text,coalesce((select invoice_number_padding from settings),6),'0') else 'INV-'||@year||'-'||lpad(allocated::text,6,'0') end from allocated""",t);Add(c,"year",year);Add(c,"numberBranch",Branch);return Convert.ToString(await c.ExecuteScalarAsync(t))!;}
 async Task<int> Exec(string s,Action<DbCommand>b,CancellationToken t){await using var c=await Command(s,t);b(c);return await c.ExecuteNonQueryAsync(t);}async Task<List<T>> Query<T>(string s,Action<DbCommand>b,Func<DbDataReader,T>m,CancellationToken t){var a=new List<T>();await using var c=await Command(s,t);b(c);await using var d=await c.ExecuteReaderAsync(t);while(await d.ReadAsync(t))a.Add(m(d));return a;}async Task<DbCommand> Command(string s,CancellationToken t){var n=db.Database.GetDbConnection();if(n.State!=ConnectionState.Open)await n.OpenAsync(t);var c=n.CreateCommand();c.Transaction=db.Database.CurrentTransaction?.GetDbTransaction();c.CommandText=s;Add(c,"organization",tenant.OrganizationId);Add(c,"branch",Branch);Add(c,"wide",tenant.IsOrganizationWide);Add(c,"actor",user.UserName);return c;}static void Add(DbCommand c,string n,object?v){if(c.Parameters.Contains(n))return;var p=c.CreateParameter();p.ParameterName=n;if(n=="funder")p.DbType=DbType.Guid;p.Value=v??DBNull.Value;c.Parameters.Add(p);}void Audit(string a,string e,Guid?id)=>db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),a,user.UserName,e,id,DateTimeOffset.UtcNow,tenant.OrganizationId,Branch));
 sealed record EligibleEvent(Guid Id,Guid? VisitId,Guid ServiceUserId,Guid FunderId,string FunderName,Guid BranchId,DateOnly Date,decimal Quantity,decimal UnitRate,decimal Amount,string Currency,string Description,Guid? ShareId,bool IsRecharge);sealed record ProfileRow(string Name,string Address,string Email,string Phone,string Company,string VatNumber,string Remittance,int Terms,decimal VatRate,string Exemption,string? LogoType,byte[]? LogoBytes,string? LogoHash,string Currency,string CurrencySymbol,string TaxLabel,string RoundingPolicy);
}
public sealed record InvoiceRunRequest(DateOnly PeriodStart,DateOnly PeriodEnd,Guid? FunderId,string IdempotencyKey="preview");
